function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function user(){return $_SESSION['user']??null;}
function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}
function verify_csrf():void{if(!hash_equals(csrf(),$_POST['csrf']??'')){http_response_code(419);exit('Request expired. Please go back and retry.');}}
function audit(PDO $db,string $action,?string $type=null,?int $id=null,string $details=''):void{$s=$db->prepare('INSERT INTO activity_logs(user_id,action,entity_type,entity_id,details,ip_address) VALUES(?,?,?,?,?,?)');$s->execute([user()['id']??null,$action,$type,$id,substr($details,0,500),$_SERVER['REMOTE_ADDR']??null]);}
function go(string $url):never{header('Location: '.$url);exit;}
function require_role(array $roles):void{if(!user())go('?page=login');if(!in_array(user()['role'],$roles,true)){http_response_code(403);exit('Access denied.');}}
function assert_clinician_case(PDO $db,int $caseId):void{$q=$db->prepare('SELECT id FROM recovery_cases WHERE id=? AND (assigned_clinician_id=? OR assigned_clinician_id IS NULL)');$q->execute([$caseId,user()['id']]);if(!$q->fetchColumn()){http_response_code(404);exit('Case unavailable in your authorized scope.');}}
$page=$_GET['page']??'home';$flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$act=$_POST['action']??'';
 if($act==='captcha'){$_SESSION['captcha_a']=random_int(1,9);$_SESSION['captcha_b']=random_int(1,9);$_SESSION['captcha_exp']=time()+180;go('?page=login');}
 if($act==='register'){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';$student=trim($_POST['student_id']??'');$sport=(int)($_POST['sport_id']??0);if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<12||!$student){$_SESSION['flash']='Complete all fields; password must contain at least 12 characters.';go('?page=register');}try{$db->beginTransaction();$st=$db->prepare("INSERT INTO users(role_id,full_name,email,password_hash) VALUES((SELECT id FROM roles WHERE name='athlete'),?,?,?)");$st->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);$id=(int)$db->lastInsertId();$st=$db->prepare('INSERT INTO athlete_profiles(user_id,student_id,sport_id) VALUES(?,?,?)');$st->execute([$id,$student,$sport?:null]);$db->commit();audit($db,'registration','user',$id);$_SESSION['flash']='Account created. You may now sign in.';}catch(Throwable $ex){if($db->inTransaction())$db->rollBack();$_SESSION['flash']='Registration could not be completed. Check that the email and student ID are unique.';}go('?page=login');}
 if($act==='login'){$a=$_SESSION['captcha_a']??null;$b=$_SESSION['captcha_b']??null;$ok=isset($a,$b)&&time()<=($_SESSION['captcha_exp']??0)&&(int)($_POST['captcha']??-1)===$a+$b;unset($_SESSION['captcha_a'],$_SESSION['captcha_b'],$_SESSION['captcha_exp']);$st=$db->prepare('SELECT u.id,u.full_name,u.email,u.password_hash,r.name role FROM users u JOIN roles r ON r.id=u.role_id WHERE u.email=? AND u.active=1');$st->execute([strtolower(trim($_POST['email']??''))]);$u=$st->fetch();if($ok&&$u&&password_verify($_POST['password']??'',$u['password_hash'])){if(password_needs_rehash($u['password_hash'],PASSWORD_DEFAULT)){$db->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),$u['id']]);}session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['full_name'],'email'=>$u['email'],'role'=>$u['role']];audit($db,'login','user',(int)$u['id']);go('?page=dashboard');}$_SESSION['flash']='Sign-in failed. Check your credentials and arithmetic answer.';go('?page=login');}
 if($act==='logout'){audit($db,'logout','user',(int)user()['id']);$_SESSION=[];session_destroy();go('?page=home');}
 if($act==='report'){require_role(['athlete']);$st=$db->prepare('INSERT INTO recovery_cases(athlete_user_id,summary,concern) VALUES(?,?,?)');$st->execute([user()['id'],trim($_POST['summary']??''),trim($_POST['concern']??'')]);$id=(int)$db->lastInsertId();audit($db,'case_submitted','case',$id);$_SESSION['flash']='Concern submitted to authorized personnel.';go('?page=cases');}
 if($act==='review'){require_role(['clinician']);$id=(int)$_POST['case_id'];assert_clinician_case($db,$id);$st=$db->prepare("UPDATE recovery_cases SET status='under_review',assigned_clinician_id=? WHERE id=?");$st->execute([user()['id'],$id]);$db->prepare('INSERT INTO case_reviews(case_id,reviewer_id,outcome,note) VALUES(?,?,?,?)')->execute([$id,user()['id'],'reviewed',trim($_POST['note']??'')]);audit($db,'case_reviewed','case',$id);go('?page=cases');}
 if($act==='milestone'){require_role(['clinician']);assert_clinician_case($db,(int)$_POST['case_id']);$db->prepare('INSERT INTO recovery_milestones(case_id,label,status,note,recorded_by) VALUES(?,?,?,?,?)')->execute([(int)$_POST['case_id'],trim($_POST['label']),$_POST['status'],trim($_POST['note']??''),user()['id']]);audit($db,'milestone_added','case',(int)$_POST['case_id']);go('?page=cases');}
 if($act==='clearance'){require_role(['clinician']);$id=(int)$_POST['case_id'];assert_clinician_case($db,$id);$db->prepare('INSERT INTO clearance_records(case_id,clinician_id,decision,valid_until,note) VALUES(?,?,?,?,?)')->execute([$id,user()['id'],$_POST['decision'],$_POST['valid_until']?:null,trim($_POST['note']??'')]);audit($db,'clearance_recorded','case',$id);go('?page=cases');}
 if($act==='eval'){require_role(['admin','clinician']);$id=(int)$_POST['case_id'];if(user()['role']==='clinician')assert_clinician_case($db,$id);$q=$db->prepare('SELECT * FROM recovery_cases WHERE id=?');$q->execute([$id]);$case=$q->fetch();if(!$case)go('?page=cases');$docs=$db->prepare("SELECT COUNT(*) FROM recovery_milestones WHERE case_id=? AND status IN('documented','reviewed')");$docs->execute([$id]);$hasDoc=(int)$docs->fetchColumn()>0;$c=$db->prepare('SELECT decision,valid_until FROM clearance_records WHERE case_id=? ORDER BY recorded_at DESC LIMIT 1');$c->execute([$id]);$clear=$c->fetch();$valid=$clear&&$clear['decision']==='cleared'&&(!$clear['valid_until']||$clear['valid_until']>=date('Y-m-d'));$pending=$case['status']==='submitted';$checks=[['Required milestone documented',$hasDoc],['Current clinician clearance recorded',$valid],['Case has been reviewed',!$pending]];$outcome=(!$pending&&$hasDoc&&$valid)?'documentation_complete':'documentation_incomplete';$explain=implode('; ',array_map(fn($x)=>$x[0].': '.($x[1]?'yes':'no'),$checks)).'. This is a documentation check only and does not determine medical safety or participation eligibility.';$db->beginTransaction();$rid=(int)$db->query('SELECT id FROM dss_rules WHERE active=1 ORDER BY id DESC LIMIT 1')->fetchColumn();$db->prepare('INSERT INTO dss_evaluations(case_id,rule_id,outcome,explanation,evaluated_by) VALUES(?,?,?,?,?)')->execute([$id,$rid,$outcome,$explain,user()['id']]);$eid=(int)$db->lastInsertId();$ins=$db->prepare('INSERT INTO dss_evaluation_details(evaluation_id,check_name,passed,detail) VALUES(?,?,?,?)');foreach($checks as $x)$ins->execute([$eid,$x[0],$x[1],$x[1]?'Requirement documented':'Requirement not documented']);$db->commit();audit($db,'dss_evaluated','case',$id);$_SESSION['flash']='Saved explainable documentation review. This is not medical clearance.';go('?page=cases');}
 if($act==='appointment'){require_role(['clinician']);assert_clinician_case($db,(int)$_POST['case_id']);$db->prepare('INSERT INTO follow_up_appointments(case_id,scheduled_at,purpose,created_by) VALUES(?,?,?,?)')->execute([(int)$_POST['case_id'],$_POST['scheduled_at'],trim($_POST['purpose']),user()['id']]);audit($db,'followup_scheduled','case',(int)$_POST['case_id']);go('?page=cases');}
