function player_entries():array{$file=__DIR__.'/../docs/100players.md';$content=is_file($file)?file_get_contents($file):'';preg_match_all('/^\d+\. (.+?)\s+—\s+(.+)$/mu',$content,$matches,PREG_OFFSET_CAPTURE);$players=[];foreach($matches[0] as $i=>$whole){$start=$whole[1];$end=$matches[0][$i+1][1]??strlen($content);$heading=$matches[1][$i][0];if(!preg_match('/^(.+?)\s+\(([^()]*)\)$/u',$heading,$parts))continue;$name=trim($parts[1]);$id='player-'.($i+1);$players[$id]=['name'=>$name,'country'=>trim($parts[2]),'sport'=>trim($matches[2][$i][0]),'body'=>trim(substr($content,$start,$end-$start))];}return $players;}
