ach'):?><th>Case action</th><?php else:?><th>Clearance indicator</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $c):?><tr><td>#<?=e($c['id'])?></td><td><?=e($c['athlete'])?></td><?php if($role!=='coach'):?><td><?=e(date('Y-m-d',strtotime($c['reported_at'])))?></td><td><span class="pill"><?=e(str_replace('_',' ',$c['status']))?></span></td><?php endif;?><td><?php if($role==='coach'){$clr=$db->prepare("SELECT decision,valid_until FROM clearance_records WHERE case_id=? ORDER BY recorded_at DESC LIMIT 1");$clr->execute([$c['id']]);$cv=$clr->fetch();$current=$cv&&(!$cv['valid_until']||$cv['valid_until']>=date('Y-m-d'));$part=$current?ucwords(str_replace('_',' ',$cv['decision'])):'No current clearance record';echo e('Medical clearance: '.$part);}elseif($role==='clinician'||$role==='admin'){?><details><summary>Manage case</summary><div class="detail"><?php if($role==='clinician'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="review"><input type="hidden" name="case_id" value="<?=$c['id']?>"><label>Review note<textarea name="note" rows="2"></textarea></label><button class="smallbtn">Start review</button></form><?php endif;?><?php if($role==='clinician'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="milestone"><input type="hidden" name="case_id" value="<?=$c['id']?>"><label>Milestone label<input name="label" required></label><label>Status<select name="status"><option>documented</option><option>reviewed</option><option>pending</option></select></label><label>Note<textarea name="note" rows="2"></textarea></label><button class="smallbtn">Add milestone</button></form><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="appointment"><input type="hidden" name="case_id" value="<?=$c['id']?>"><label>Follow-up date and time<input type="datetime-local" name="scheduled_at" required></label><label>Purpose<input name="purpose" required></label><button class="smallbtn">Schedule follow-up</button></form><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="clearance"><input type="hidden" name="case_id" value="<?=$c['id']?>"><label>Clinician decision<select name="decision"><option value="not_cleared">Not cleared</option><option value="restricted">Restricted</option><option value="cleared">Cleared</option></select></label><label>Valid until (optional)<input type="date" name="valid_until"></label><label>Record note<textarea name="note" rows="2"></textarea></label><button class="smallbtn">Record clearance decision</button></form><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="eval"><input type="hidden" name="case_id" value="<?=$c['id']?>"><button class="smallbtn">Evaluate documentation readiness</button></form><?php if($role==='clinician'):?><p class="muted">Concern: <?=e($c['concern'])?></p><?php endif;?></div></details><?php } else {?>Your own case<?php }?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><p class="empty">No cases are available in your scope.</p><?php endif;?></div><?php break;
