function markdown_basic(string $s):string{$s=htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$lines=explode("\n",$s);$out='';$in=false;$ol=false;foreach($lines as $line){if(preg_match('/^([A-J])\. (.+)$/u',$line,$m)){if($in){$out.=$ol?'</ol>':'</ul>';$in=$ol=false;}$out.='<h2>'.$m[1].'. '.$m[2].'</h2>';continue;}if(preg_match('/^#{1,6} (.+)$/',$line,$m)){if($in){$out.=$ol?'</ol>':'</ul>';$in=$ol=false;}$out.='<h2>'.$m[1].'</h2>';continue;}if(preg_match('/^\d+\. (.+)$/',$line,$m)){if(!$in||!$ol){if($in)$out.='</ul>';$out.='<ol>';$in=$ol=true;}$out.='<li>'.$m[1].'</li>';continue;}if(preg_match('/^\* (.+)$/',$line,$m)){if(!$in||$ol){if($in)$out.='</ol>';$out.='<ul>';$in=true;$ol=false;}$out.='<li>'.$m[1].'</li>';continue;}if($in){$out.=$ol?'</ol>':'</ul>';$in=$ol=false;}if(trim($line)!==''){$text=preg_replace('/\*\*(.+?)\*\*/u','<strong>$1</strong>',$line);$text=preg_replace('/(?<!\*)\*([^*]+)\*(?!\*)/u','<em>$1</em>',$text);$out.='<p>'.$text.'</p>';}}if($in)$out.=$ol?'</ol>':'</ul>';return $out;}
